WITH cleaned AS (SELECT id, reading_ts, temp_c, humidity, pressure, FLOOR(humidity) AS humidity_whole, LENGTH(device_code) AS device_code_length FROM device_readings WHERE pressure <= 995) SELECT id, temp_c, humidity, humidity_whole, device_code_length, FIRST_VALUE(humidity, TRUE) OVER (ORDER BY humidity_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_humidity, SUM(device_code_length) OVER (ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_device_code_length, FIRST_VALUE(humidity) IGNORE NULLS OVER (ORDER BY humidity_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_humidity_2, NTILE(5) OVER (ORDER BY device_code_length DESC, id) AS device_code_length_bucket, FIRST_VALUE(pressure, TRUE) OVER (ORDER BY device_code_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_pressure FROM cleaned WHERE humidity BETWEEN 47 AND 71;
